private lemma orderTop_n_sub_lambdaPrincipal_mul_d [Nontrivial R] :
    ((1 : ℤ) : WithTop ℤ) ≤
      ((W.biY₂ - W.biY₁) - W.lambdaPrincipal * (W.biX₂ - W.biX₁)).orderTop

private lemma formalYThree_sub_biY₁_eq :
    W.formalYThree - W.biY₁
      = W.zpureY + (W.formalLambda - W.lambdaPrincipal) * W.qY

private lemma lam_sub_prin_mul_d :
    (W.formalLambda - W.lambdaPrincipal) * (W.biX₂ - W.biX₁)
      = (W.biY₂ - W.biY₁) - W.lambdaPrincipal * (W.biX₂ - W.biX₁)

private lemma orderTop_d_sub_single [Nontrivial R] :
    ((-1 : ℤ) : WithTop ℤ)
      ≤ ((W.biX₂ - W.biX₁) - HahnSeries.single (-2) 1).orderTop

private lemma coeff_lam_sub_prin_mul_d_one [Nontrivial R] :
    ((W.formalLambda - W.lambdaPrincipal) * (W.biX₂ - W.biX₁)).coeff 1
      = (W.formalLambda - W.lambdaPrincipal).coeff 3

private lemma coeff_lambda_mul_formalXThree_one [Nontrivial R] :
    (W.formalLambda * W.formalXThree).coeff 1
      = -W.formalXThree.coeff 2 - W.formalX ^ 2

private theorem coeff_mul_X_shift (φ : MvPowerSeries (Fin 2) R) (s : Fin 2)
    (m : Fin 2 →₀ ℕ) :
    MvPowerSeries.coeff (m + Finsupp.single s 1) (φ * X s) = MvPowerSeries.coeff m φ

private lemma order_add₄_ge {a b c d : R⟦X⟧} {k : ℕ∞}
    (ha : k ≤ a.order) (hb : k ≤ b.order) (hc : k ≤ c.order) (hd : k ≤ d.order) :
    k ≤ (a + b + c + d).order

