private lemma orderTop_sub_leading_ge [Nontrivial R] {x : (R⸨X⸩)⸨X⸩}
    (hx : x.orderTop = (0 : WithTop ℤ)) :
    ((1 : ℤ) : WithTop ℤ) ≤ (x - HahnSeries.single 0 (x.coeff 0)).orderTop

private lemma coeff_mul_one_of_orderTop_zero [Nontrivial R] {a b : (R⸨X⸩)⸨X⸩}
    (ha : a.orderTop = (0 : WithTop ℤ)) (hb : b.orderTop = (0 : WithTop ℤ)) :
    (a * b).coeff 1 = a.coeff 1 * b.coeff 0 + a.coeff 0 * b.coeff 1

theorem constantCoeff_formalLog_subst [Algebra ℚ R] {G : MvPowerSeries (Fin 2) R}
    (hG0 : MvPowerSeries.constantCoeff G = 0) :
