private theorem coordChangeZ_sub_biZ₁_mul {R : Type*} [CommRing R] (W : WeierstrassCurve R) :
    (W.coordChangeZ - W.biZ₁) * (W.secantY * W.biY₁)
      = -W.formalNu * (W.formalXThree - W.biX₁)

private theorem coordChangeZ_sub_biZ₂_mul {R : Type*} [CommRing R] (W : WeierstrassCurve R) :
    (W.coordChangeZ - W.biZ₂) * (W.secantY * W.biY₂)
      = -W.formalNu * (W.formalXThree - W.biX₂)

